class Fendix < Formula
  desc "Application security scanner with evidence-backed release decisions"
  homepage "https://fendix.dev"
  license "MIT"
  version_scheme 1

  depends_on "python@3.11" => :recommended

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/Fendix-app/Fendix/releases/download/v3.6.5/fendix-v3.6.5-darwin-arm64"
      sha256 "4e391d883382f1d3d490d5291237202ff1a0d0f69bcf485d2cd0bdac1a9d90ac"
    else
      url "https://github.com/Fendix-app/Fendix/releases/download/v3.6.5/fendix-v3.6.5-darwin-amd64"
      sha256 "19a583058816014f5c819858c77eebf28c38cc8d1bb9960093b02c26a0abae76"
    end
  end

  on_linux do
    if Hardware::CPU.arm?
      url "https://github.com/Fendix-app/Fendix/releases/download/v3.6.5/fendix-v3.6.5-linux-arm64"
      sha256 "ab0734877d5b57dfb0664b6ca3b316cf2a68918bdb226cc174b2b15b99fb48ab"
    else
      url "https://github.com/Fendix-app/Fendix/releases/download/v3.6.5/fendix-v3.6.5-linux-amd64"
      sha256 "a693593d976fdafee2b594596e54b9b3d7a34bc86888168fb0a3ed4ee2e0aa51"
    end
  end

  def install
    bin.install Dir["fendix-*"].first => "fendix"
  end

  def caveats
    <<~EOC
      This formula installs the standalone Go binary and recommends a Python
      interpreter, but it does not install the Fendix Python analyzer tree.
      --code auto-enables that phase; without a version-matched tree through
      FENDIX_ENGINE or an engine pin, the phase is recorded as skipped while
      native analyzers continue. Use the official container or a source
      checkout for ready-to-run hybrid coverage.

      Quick start:
        fendix scan --url https://api.example.com
        fendix scan --code ./src --python-engine=false --format html -o report.html
    EOC
  end

  test do
    assert_match "fendix version", shell_output("#{bin}/fendix version")
  end
end
